<?php
declare(strict_types=1);
namespace App\Models;
use App\Core\Database;use PDO;use Throwable;
final class GlobalSearch
{
    public static function query(string $term,int $limit=8): array
    {
        $term=trim($term);$empty=['players'=>[],'referees'=>[],'coaches'=>[],'teams'=>[],'player_posts'=>[],'opponent_posts'=>[]];if(strlen($term)<2)return$empty;$like='%'.$term.'%';$limit=max(1,min(12,$limit));$pdo=Database::connection();
        try{$p=$pdo->prepare('SELECT u.id,u.display_name,u.username,u.province,u.district,u.profile_verified_at,p.primary_position,p.avatar_path FROM users u INNER JOIN player_profiles p ON p.user_id=u.id INNER JOIN user_football_identities fi ON fi.user_id=u.id AND fi.identity_type="recreational_player" AND fi.status="active" WHERE u.status="active" AND p.visibility="public" AND (u.display_name LIKE :q1 OR u.username LIKE :q2 OR u.province LIKE :q3 OR u.district LIKE :q4) ORDER BY u.last_seen_at DESC LIMIT '.$limit);$p->execute(['q1'=>$like,'q2'=>$like,'q3'=>$like,'q4'=>$like]);$players=$p->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable){$players=[];}
        try{$r=$pdo->prepare('SELECT r.id,r.slug,r.classification,r.license_status,r.availability_status,r.province,r.district,u.display_name,u.username,u.profile_verified_at,p.avatar_path FROM referee_profiles r INNER JOIN users u ON u.id=r.user_id LEFT JOIN player_profiles p ON p.user_id=u.id WHERE r.status="active" AND u.status="active" AND (u.display_name LIKE :q1 OR u.username LIKE :q2 OR r.classification LIKE :q3 OR r.province LIKE :q4 OR r.district LIKE :q5) ORDER BY (r.license_status="verified") DESC,r.updated_at DESC LIMIT '.$limit);$r->execute(['q1'=>$like,'q2'=>$like,'q3'=>$like,'q4'=>$like,'q5'=>$like]);$referees=$r->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable){$referees=[];}
        try{$c=$pdo->prepare('SELECT c.id,c.slug,c.public_title,c.license_level,c.license_status,c.intent,c.province,c.district,u.display_name,u.username,u.profile_verified_at,p.avatar_path FROM coach_profiles c INNER JOIN users u ON u.id=c.user_id LEFT JOIN player_profiles p ON p.user_id=u.id WHERE c.status="active" AND u.status="active" AND (u.display_name LIKE :q1 OR u.username LIKE :q2 OR c.public_title LIKE :q3 OR c.license_level LIKE :q4 OR c.province LIKE :q5 OR c.district LIKE :q6) ORDER BY (c.license_status="verified") DESC,c.updated_at DESC LIMIT '.$limit);$c->execute(['q1'=>$like,'q2'=>$like,'q3'=>$like,'q4'=>$like,'q5'=>$like,'q6'=>$like]);$coaches=$c->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable){$coaches=[];}
        $t=$pdo->prepare('SELECT id,name,slug,province,district,logo_path FROM teams WHERE status="active" AND (name LIKE :q1 OR province LIKE :q2 OR district LIKE :q3) ORDER BY created_at DESC LIMIT '.$limit);$t->execute(['q1'=>$like,'q2'=>$like,'q3'=>$like]);
        $pw=$pdo->prepare('SELECT p.id,p.position,p.match_at,p.province,p.district,t.name team_name FROM player_wanted_posts p INNER JOIN teams t ON t.id=p.team_id WHERE p.status="open" AND p.match_at>=NOW() AND (p.position LIKE :q1 OR p.province LIKE :q2 OR p.district LIKE :q3 OR t.name LIKE :q4) ORDER BY p.match_at ASC LIMIT '.$limit);$pw->execute(['q1'=>$like,'q2'=>$like,'q3'=>$like,'q4'=>$like]);
        $op=$pdo->prepare('SELECT p.id,p.match_at,p.province,p.district,p.match_format,p.level,t.name team_name FROM opponent_posts p INNER JOIN teams t ON t.id=p.team_id WHERE p.status="open" AND p.match_at>=NOW() AND (p.province LIKE :q1 OR p.district LIKE :q2 OR p.match_format LIKE :q3 OR t.name LIKE :q4) ORDER BY p.match_at ASC LIMIT '.$limit);$op->execute(['q1'=>$like,'q2'=>$like,'q3'=>$like,'q4'=>$like]);
        return['players'=>$players,'referees'=>$referees,'coaches'=>$coaches,'teams'=>$t->fetchAll(PDO::FETCH_ASSOC)?:[],'player_posts'=>$pw->fetchAll(PDO::FETCH_ASSOC)?:[],'opponent_posts'=>$op->fetchAll(PDO::FETCH_ASSOC)?:[]];
    }
}
